import pandas as pd

# Filter rows where character contains '斤' or '担' or '擔'
relevant_rows = df[df['character'].str.contains('斤|担|擔')]

# Check if all filtered rows have relative value >= 1
# Convert relative value strings to numeric values
def parse_relative_value(val_str):
    if '/' in val_str:
        num, denom = val_str.split('/')
        return float(num.strip()) / float(denom.strip())
    else:
        return float(val_str)

relative_values = relevant_rows['relative value'].apply(parse_relative_value)
answer = all(value >= 1 for value in relative_values)
